-- ------------------------------------------------------------
-- V45：外贸客户开发流水线 + 外贸业务员预设
-- 平台内置：面向外贸业务场景的客户开发自动化流水线，
-- 搭配专属外贸业务员预设人格使用。
-- ------------------------------------------------------------

-- 外贸业务员预设人格
INSERT INTO agent_preset (scope, tenant_id, agent_code, agent_name, icon, description, sys_prompt, order_num)
SELECT 'PLATFORM', 0, 'foreign-trade', '外贸业务员', 'search',
'外贸客户开发与商务沟通助手，精通国际贸易与英文商务写作',
'# 外贸业务员助手（ForeignTradeAgent）\n\n你是一名资深外贸业务员 AI 助手，精通国际贸易、客户开发与商务沟通。\n\n## 核心能力\n1. **客户开发**：熟悉全球主要市场的进口商、分销商网络，擅长通过搜索引擎、行业目录、展会信息等渠道挖掘潜在客户\n2. **商务沟通**：精通英文商务邮件写作，能根据客户背景定制个性化开发信（Cold Email），语言地道，避免中式英语\n3. **市场分析**：了解主要国家/地区的贸易政策、关税壁垒、市场准入要求\n4. **全流程支持**：熟悉外贸全流程——询盘 → 报价 → 样品 → 订单 → 出货 → 售后\n\n## 工作风格\n- 专业、简洁、结果导向\n- 搜索时使用英文关键词（国际贸易通用语言）\n- 开发信用地道商务英语，语气专业而不生硬\n- 重要数据和联系方式用表格呈现，方便复制使用\n- 搜索关键词给出中英对照，方便用户理解搜索策略\n\n## 限制\n- 不编造公司信息和联系方式，搜不到就如实标注"待补充"\n- 不替用户做最终商务决策，只提供信息和建议\n- 涉及报价时提醒用户结合实际成本和利润核算\n- 邮件模板中标注需要用户替换的变量（如 {company_name}、{product_name}）',
7
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agent_preset WHERE scope = 'PLATFORM' AND agent_code = 'foreign-trade');

-- 外贸客户开发流水线
INSERT INTO agent_pipeline (scope, tenant_id, pipeline_code, pipeline_name, description, steps, exception_handling, order_num)
SELECT 'PLATFORM', 0, 'foreign-trade-lead-gen', '外贸客户开发流水线',
'目标市场分析 → 多渠道客户搜索 → 信息深挖 → 客户分级 → 开发信撰写，全流程自动化',
'## 执行步骤（顺序执行，每步输出结构化结果）\n\n### Step 1: 明确目标市场与产品定位（researcher）\n- 与用户确认：目标国家/地区、产品类目、核心卖点、价格区间\n- 若用户已提供明确信息则跳过确认，直接生成市场画像\n- 输出：市场画像摘要（目标市场 + 产品关键词 + 搜索策略）\n- 等待用户确认后进入下一步\n\n### Step 2: 多渠道潜在客户搜索（researcher）\n- 根据 Step 1 的市场画像，使用 web_search 工具分批搜索：\n  a) 搜索 "{产品关键词} importers in {目标国家}"，提取进口商/分销商\n  b) 搜索 "{产品关键词} buyers directory {目标国家}"，提取行业目录\n  c) 搜索 "{目标国家} {产品} trade show exhibitors"，提取展会参展商\n  d) 搜索 "{目标国家} {产品} wholesale distributor"，提取批发商\n- 每个渠道至少搜索 2 轮，用不同关键词组合扩大覆盖面\n- 输出：原始线索清单（公司名 + 网站 + 简要描述）\n\n### Step 3: 客户信息深度挖掘（researcher）\n- 对 Step 2 的每条线索，使用 web_search 进一步搜索：\n  a) 公司官网，提取联系方式（邮箱、电话、地址）\n  b) 公司规模、主营业务、采购需求\n  c) LinkedIn / 社交媒体上的关键决策人\n- 输出：每家公司的详细档案（公司名、网站、联系人、邮箱、电话、规模、主营、采购信号）\n\n### Step 4: 客户分级与筛选（researcher）\n- 按以下维度对线索打分（1-5 分）：\n  a) 产品匹配度：主营产品与目标产品的相关性\n  b) 规模适配性：公司规模是否在目标客户范围内\n  c) 采购信号强度：是否有近期采购/招标/询盘迹象\n  d) 联系可达性：是否找到有效联系方式\n- 输出：分级客户列表（A 级 ≥ 16 分 / B 级 10-15 分 / C 级 < 10 分）\n- 只保留 A、B 级客户进入下一步\n\n### Step 5: 整理客户档案并存档（researcher）\n- 将筛选后的客户信息整理为结构化表格（Markdown 格式）\n- 使用文件系统工具保存到工作区：customers/leads-{目标市场}-{日期}.md\n- 输出：客户档案文件（含公司名、联系人、邮箱、电话、分级、备注）\n\n### Step 6: 撰写个性化开发信（writer）\n- 为 A 级客户各撰写一封个性化开发信：\n  a) 开头提及对方公司/产品，体现做过功课\n  b) 突出我方产品优势与对方需求的契合点\n  c) 包含明确的 CTA（行动号召）\n  d) 语言：英文为主，根据目标市场调整\n- B 级客户使用半模板化邮件（统一框架 + 少量定制）\n- 输出：开发信草稿列表（每封信含收件人、主题、正文）\n\n### Step 7: 汇总报告（researcher）\n- 汇总本次开发成果：\n  a) 搜索覆盖：搜索了多少关键词、多少渠道\n  b) 线索统计：原始线索数 → 有效线索数 → A/B 级客户数\n  c) 下一步建议：推荐优先联系的客户、建议的后续动作\n- 输出：开发报告摘要',
'## 异常处理\n- Step 1 用户未确认 → 最多追问 2 轮，仍无明确方向则基于默认假设继续\n- Step 2 某渠道搜索失败 → 跳过该渠道，在报告中标注，用其他渠道补充\n- Step 3 某公司官网无法访问 → 标记为"信息不完整"，继续处理其他公司\n- Step 4 A 级客户为 0 → 放宽筛选标准，将 B 级前 5 名提升为 A 级\n- Step 6 找不到联系人邮箱 → 开发信标注"待补充邮箱"，建议通过 LinkedIn 或官网表单联系',
4
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM agent_pipeline WHERE scope = 'PLATFORM' AND pipeline_code = 'foreign-trade-lead-gen');
